{
  "findings": [
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 bucket lacks lifecycle configuration",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The bucket has no lifecycle configuration, so incomplete multipart uploads can remain indefinitely and consume storage."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "No bucket-level Public Access Block is configured, allowing future ACL or bucket policy changes to expose the bucket publicly."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is disabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "HIGH",
      "explanation": "The bucket does not record server access requests, reducing the ability to investigate unauthorized or suspicious access."
    },
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 cross-region replication is disabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The bucket has no replication configuration, leaving its contents without cross-region resilience if the source region becomes unavailable."
    },
    {
      "check_id": "CKV_AWS_53",
      "title": "S3 public ACLs are not blocked",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "CRITICAL",
      "explanation": "The bucket does not block public ACLs, so a public ACL could expose stored objects to unauthenticated users."
    }
  ],
  "patched_code": "variable "access_log_target_bucket" {
  description = "Name of a pre-existing same-region S3 bucket configured to receive S3 server access logs."
  type        = string
}

variable "replication_destination_bucket_arn" {
  description = "ARN of a pre-existing versioned S3 bucket in a different AWS region used as the replication destination."
  type        = string

  validation {
    condition     = can(regex("^arn:[^:]+:s3:::[^/]+$", var.replication_destination_bucket_arn))
    error_message = "replication_destination_bucket_arn must be a valid S3 bucket ARN."
  }
}

resource "aws_s3_bucket" "changeme_aws_s3_bucket_backend_simple" {
  force_destroy = true
  bucket        = "changeme-${random_id.changeme_backends_s3_bucket_name.hex}"
}

resource "aws_s3_bucket_public_access_block" "changeme_aws_s3_bucket_backend_simple" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "changeme_aws_s3_bucket_backend_simple" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_logging" "changeme_aws_s3_bucket_backend_simple" {
  bucket        = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id
  target_bucket = var.access_log_target_bucket
  target_prefix = "s3-access-logs/${aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id}/"
}

resource "aws_s3_bucket_versioning" "changeme_aws_s3_bucket_backend_simple" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "changeme_aws_s3_bucket_backend_simple_replication" {
  name = "changeme-s3-replication-${random_id.changeme_backends_s3_bucket_name.hex}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "changeme_aws_s3_bucket_backend_simple_replication" {
  name = "changeme-s3-replication"
  role = aws_iam_role.changeme_aws_s3_bucket_backend_simple_replication.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = "${aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = "${var.replication_destination_bucket_arn}/*"
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "changeme_aws_s3_bucket_backend_simple" {
  depends_on = [aws_s3_bucket_versioning.changeme_aws_s3_bucket_backend_simple]

  bucket = aws_s3
